// Generated by /ship review fixes (Claude) — 2026-10-13
// Value: protects=/classes hands ClassListPage canImportClasses only with imports.classes, so "Nhập lớp từ file" shows for importers and nobody else;
// fails_when=the flag keys off the wrong permission (e.g. classes.create), is hard-coded, or stops reaching the page (it defaults to false and the button disappears);
// why_new=permission wiring lives only in the route; presentation tests pass canImportClasses as a prop;
// seam=none (loader and ClassListPage mocked at module boundaries; returned element props inspected); no_claim=does not prove /imports/classes enforces imports.classes itself
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import ClassesRoute from "@/app/(app)/classes/page";
import type { ClassListPage } from "@/features/classes/class-list-page";

const dependencies = vi.hoisted(() => ({
  ClassListPage: vi.fn(() => null),
  getCachedDatabasePermissions: vi.fn(),
  getClassDirectory: vi.fn(),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/classes/data", () => ({ getClassDirectory: dependencies.getClassDirectory }));
vi.mock("@/features/classes/class-list-page", () => ({ ClassListPage: dependencies.ClassListPage }));

async function renderRoute(permissions: string[]) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getClassDirectory.mockResolvedValue({ classes: [], ok: true });

  return (await ClassesRoute()) as ReactElement<ComponentProps<typeof ClassListPage>>;
}

afterEach(() => {
  vi.clearAllMocks();
});

describe("Classes route import permission wiring", () => {
  it("maps imports.classes to canImportClasses", async () => {
    const without = await renderRoute(["classes.view", "classes.create"]);
    expect(without.type).toBe(dependencies.ClassListPage);
    expect(without.props.canImportClasses).toBe(false);
    expect(without.props.canCreateClass).toBe(true);

    const withImport = await renderRoute(["classes.view", "imports.classes"]);
    expect(withImport.props.canImportClasses).toBe(true);
    expect(withImport.props.canCreateClass).toBe(false);
  });
});
